"""Standard published idle/sync vectors plus independently polynomial-built words."""
import unittest
import numpy as np
from rfatlas.pocsag import valid_word,batches,POCSAGDecoder
from rfatlas.decoders import DecoderInput,run_decoder


def words_bits(words):
    return np.unpackbits(np.frombuffer(b''.join(w.to_bytes(4,'big') for w in words),dtype=np.uint8))


def fixture_bits(corrupt=False,preamble=True):
    # Published M.584 idle word, not generated by the recognizer under test.
    words=[0x7A89C197]*16
    if corrupt:words[7]^=0x4000
    return np.r_[np.tile([1,0],288) if preamble else [],words_bits([0x7CD215D8,*words])].astype(np.uint8)


def waveform(baud=1200,corrupt=False,polarity=1,rate=48000):
    bits=fixture_bits(corrupt);n=round(len(bits)*rate/baud)
    indices=np.minimum((np.arange(n)*baud/rate).astype(int),len(bits)-1)
    # Deliberate CFO and reversed polarity; no receiver/transmission involved.
    hz=polarity*(bits[indices].astype(float)*2-1)*4500+1300
    return .25*np.exp(2j*np.pi*np.cumsum(hz)/rate)


class POCSAGTests(unittest.TestCase):
    def test_ambiguous_narrowband_does_not_displace_existing_dmr_attempt(self):
        from unittest.mock import patch
        from rfatlas.identification import default_registry,select_candidates,DecoderRegistry
        # Four-attempt budget historically fits three sensor decoders and DMR.
        # An unmatched new subset must not consume that last established slot.
        recording=DecoderInput(np.zeros(250000,dtype=complex),250000,451300000)
        analysis=dict(modulation='UNKNOWN',features={'occupied_bandwidth_hz':2000},activity={'events':[{}]})
        with patch.object(DecoderRegistry,'available',return_value=True):
            selected=[c['decoder'] for c in select_candidates(default_registry(),recording,analysis) if c['eligible']]
        self.assertLess(selected.index('native-dmr-bs-csbk'),4)

    def test_recording_pipeline_routes_and_preserves_encryption_unknown(self):
        import hashlib,json,tempfile
        from pathlib import Path
        from rfatlas.identification import identify_recording
        with tempfile.TemporaryDirectory() as d:
            x=waveform();raw=np.column_stack((x.real,x.imag))
            data=np.clip(np.rint(raw*127.5+127.5),0,255).astype(np.uint8).tobytes()
            p=Path(d)/'constructed.cu8';p.write_bytes(data)
            p.with_suffix('.json').write_text(json.dumps(dict(format='cu8',sample_rate=48000,sample_count=len(x),center_hz=150000000,sha256=hashlib.sha256(data).hexdigest())),encoding='utf8')
            a,_=identify_recording(p)
            self.assertTrue(a['protocol_verified']);self.assertEqual(a['protocol'],'POCSAG')
            self.assertEqual(a['protection']['status'],'UNKNOWN')
            stages={s['stage']:s for s in a['pipeline_diagnostics']['recognition_hierarchy']}
            self.assertEqual(stages['PROTOCOL']['candidate'],'POCSAG')
            self.assertEqual(stages['MODULATION_FAMILY']['candidate'],'DIGITAL')
            self.assertEqual(stages['ENCRYPTION']['candidate'],'UNKNOWN')

    def test_published_idle_and_every_single_bit_negative(self):
        self.assertTrue(valid_word(0x7A89C197))
        for bit in range(32):self.assertFalse(valid_word(0x7A89C197^(1<<bit)))
        for malformed in ([256], [1.1], [float('nan')], ['1'], [[1]], np.zeros(120001)):
            with self.assertRaises(ValueError):batches(malformed)

    def test_sync_alone_truncation_missing_preamble_and_bad_bch_do_not_verify(self):
        self.assertEqual(len(batches(fixture_bits())[0]),1)
        for bits in (fixture_bits(True),fixture_bits(False,False),fixture_bits()[:-1],words_bits([0x7CD215D8])):
            self.assertFalse(batches(bits)[0])
        late=np.r_[fixture_bits(preamble=False),fixture_bits(preamble=False)]
        self.assertEqual(len(batches(late)[0]),2)

    def test_all_rates_and_polarities_verify_only_batch_metadata(self):
        for baud in (512,1200,2400):
            for polarity in (1,-1):
                with self.subTest(baud=baud,polarity=polarity):
                    a=run_decoder(POCSAGDecoder(),DecoderInput(waveform(baud,polarity=polarity),48000,150000000))
                    self.assertTrue(a['protocol_verified']);self.assertEqual(a['protocol'],'POCSAG')
                    self.assertTrue(all(f['raw_hex'] is None for f in a['frames']))
                    self.assertEqual(a['frames'][0]['parsed_fields']['symbol_rate_hz'],baud)

    def test_noise_and_corrupt_waveform_cannot_verify(self):
        rng=np.random.default_rng(171);x=.2*(rng.normal(size=100000)+1j*rng.normal(size=100000))
        for iq in (x,waveform(corrupt=True)):
            self.assertFalse(run_decoder(POCSAGDecoder(),DecoderInput(iq,48000,150000000))['protocol_verified'])
